#!/bin/sh
set -eu

# required boot files expected to exist on the current system
#
# The base package `FreeBSD-pkg-bootstrap` contains the trust keys for the
# FreeBSD repositories and a generic configuration for the FreeBSD-base
# repository that expands `ABI` and `OSVERSION` variables.
#
# The base package `FreeBSD-runtime` contains user and group database and
# the services database (text file is sufficient). The binary user database
# is required for `pkg` to work (it is generated by `pwd_mkdb`).
#
# The package `ca_root_nss` is used as the truststore to make pkg+https work.
# Alternatively, push /etc/ssl into the bootstrap image.
#
# The base package `FreeBSD-rescue` contains a static `sh` which is
# required to run multiple commands in one `podman run` invocation.
#
# The package `pkg` contains the static `pkg-static` binary.
#
# - etc/pkg usr/share/keys                 FreeBSD-pkg-bootstrap (overwritten)
# - etc/{group,pwd.db,services}            FreeBSD-runtime (overwritten)
# - usr/local/share/certs/ca-root-nss.crt  ca_root_nss (optional, deleted)
# - rescue/sh                              FreeBSD-rescue (deleted)
# - usr/local/sbin/pkg-static              pkg (deleted)
#

os_reldate="$(sysctl -n kern.osreldate)"
v_maj="${os_reldate%[0-9][0-9][0-9][0-9][0-9]}"
arch="$(sysctl -n hw.machine_arch)"

requested_maj="$v_maj"
requested_arch="$arch"
if [ -n "${ABI:-}" ]; then
    if [ -z "${OSVERSION:-}" ]; then
        echo "error: must set OSVERSION with ABI" >&2
        exit 2
    fi
    requested_maj="${ABI#*:}"
    requested_arch="${requested_maj#*:}"
    requested_maj="${requested_maj%:*}"
fi

base_conf=15
if [ "$requested_maj" -lt 15 ]; then
    base_conf=14
fi

# use base release tar + pkg tar
# - https://download.freebsd.org/releases/amd64/15.1-RELEASE/base.txz
# - https://pkg.freebsd.org/FreeBSD:15:amd64/latest/Latest/pkg.pkg
use_base_tar() {
    tar -cf - \
        --include etc/pkg \
        --include usr/share/keys \
        --include etc/group \
        --include etc/pwd.db \
        --include etc/services \
        --include rescue \
        --include etc/ssl \
        --include usr/share/certs \
        --include /usr/local/sbin/pkg-static -s '|^/||' \
        --include FreeBSD-"$base_conf".conf \
        -s '|^FreeBSD-.*\.conf|usr/local/etc/pkg/repos/FreeBSD.conf|' \
        @base-"$requested_maj"-"$requested_arch".txz \
        @pkg-"$requested_maj"-"$requested_arch".pkg \
        FreeBSD-"$base_conf".conf
}

boot_files_prefix=/

use_base_system() {
    tar -cf - \
        -C "$boot_files_prefix" \
        etc/pkg \
        usr/share/keys \
        etc/group \
        etc/pwd.db \
        etc/services \
        usr/local/share/certs/ca-root-nss.crt \
        rescue/sh \
        usr/local/sbin/pkg-static | \
    tar -cf - \
        -s '|^FreeBSD-.*\.conf|usr/local/etc/pkg/repos/FreeBSD.conf|' \
        @- FreeBSD-"$base_conf".conf
}

if [ "$requested_maj" = "$v_maj" ] && [ "$requested_arch" = "$arch" ]; then
    bid="$(use_base_system | podman import -q -)"
else
    bid="$(use_base_tar | podman import -q -)"
fi

if [ -z "$bid" ]; then
    echo "importing the bootstrap image failed" >&2
    exit 1
fi

trap 'podman rmi "$bid"' EXIT

here=$(realpath "$(dirname "$0")")
cidfile="$(mktemp /tmp/boot.cid.XXXXXXXX)"

on_exit() {
    cid="$(cat "$cidfile")"
    [ -n "$cid" ] && podman rm -f "$cid"
    [ -n "$bid" ] && podman rmi "$bid"
    rm -f "$cidfile"
}

trap on_exit EXIT

podman --runtime "$here/bin/ocijail" \
    run --cidfile "$cidfile" \
    -e ABI="${ABI:-FreeBSD:$requested_maj:$requested_arch}" \
    -e OSVERSION="${OSVERSION:-$os_reldate}" \
    "$bid" \
    /rescue/sh -c "set -e
        if [ -r /usr/local/share/certs/ca-root-nss.crt ]; then
            export SSL_CA_CERT_FILE=/usr/local/share/certs/ca-root-nss.crt
        fi
        pkg-static install -y -r FreeBSD-base \
        FreeBSD-caroot FreeBSD-openssl FreeBSD-zoneinfo \
        FreeBSD-runtime FreeBSD-rc FreeBSD-mtree FreeBSD-fetch \
        FreeBSD-libucl FreeBSD-libexecinfo FreeBSD-kerberos-lib \
        FreeBSD-pkg-bootstrap
        pkg-static install -y -r FreeBSD-base FreeBSD-certctl
        rm -Rf /rescue /usr/local/share /usr/local/sbin
        SSL_CA_CERT_FILE= certctl rehash
        service ldconfig start
        freebsd-version -u > /var/cache/pkg/.freebsd-version"

cid="$(cat "$cidfile")"
tag="$(podman cp "$cid":/var/cache/pkg/.freebsd-version - | tar -xOf -)"

podman export "$cid" | \
    tar -cf - --exclude var/cache/pkg --exclude var/db/pkg/repos @- | \
    podman import -c 'CMD /bin/sh' - freebsd-minimal:"$tag"
